def intercept_external_help_seeking(user_id, activity_data, tutor_state):

    alt_tab_count = activity_data['alt_tab_count']
    new_browser_tab_url = activity_data['new_browser_tab_url']
    clipboard_content = activity_data['clipboard_content']

    # Define thresholds
    ALT_TAB_THRESHOLD = 3
    URL_QUESTIONS = ['google.com', 'bing.com', 'wikipedia.org', 'stackoverflow.com', 'reddit.com', 'chegg.com', 'scholar.google.com', 'search?q=', 'youtube.com']
    HINT_COOLDOWN = 300 # seconds

    # Check if user likely searching externally
    external_flag = False
    if alt_tab_count >= ALT_TAB_THRESHOLD or new_browser_tab_url:
        if new_browser_tab_url:
            if any(domain in new_browser_tab_url for domain in URL_QUESTIONS):
                external_flag = True

    # Check for copying problem text
    problem_detected = False
    if clipboard_content:
        # Basic heuristic: look for numbers and 'solve', 'calculate', 'question', 'find', 'determine'
        if len(clipboard_content.split()) > 5 and ('solve' in clipboard_content.lower() or 'calculate' in clipboard_content.lower()):
            problem_detected = True

    # Decide intervention
    if problem_detected:
        # trigger scaffolding hint or peer
        if tutor_state.get('hints_remaining') > 0:
            return ('scaffolding_hint', None)
        else:
            # fallback to peer
            peer_id, motive = select_peer_for_motivation(user_id, 'frustrated', tutor_state.get('peer_db'))
            return ('relatability_peer', peer_id)
    elif external_flag:
        # Offer a gentle prompt
        if tutor_state.get('last_intervention_time') + HINT_COOLDOWN < current_time():
            return ('prompt_in_tutor', "It looks like you opened a new tab. Would you like help right here?")
    # otherwise no action
    return (None, None)

